    BASE_ACCT_NO = #{row.baseAcctNo,jdbcType=VARCHAR},            IS_CORP_SETTLE_CARD = #{row.isCorpSettleCard,jdbcType=VARCHAR},            CLIENT_NO = #{row.clientNo,jdbcType=VARCHAR},            LAST_UPD_TIMESTAMP = #{row.lastUpdTimestamp,jdbcType=VARCHAR},            ACCT_DOMAIN = #{row.acctDomain,jdbcType=VARCHAR},            ACCT_OPEN_DATE = #{row.acctOpenDate,jdbcType=TIMESTAMP},            CLOSE_BRANCH = #{row.closeBranch,jdbcType=VARCHAR},            CREATE_TIMESTAMP = #{row.createTimestamp,jdbcType=VARCHAR},            CLIENT_ACCT_STATUS = #{row.clientAcctStatus,jdbcType=VARCHAR},            ACCT_BRANCH = #{row.acctBranch,jdbcType=VARCHAR},            DOC_TYPE = #{row.docType,jdbcType=VARCHAR},            VOUCHER_NO = #{row.voucherNo,jdbcType=VARCHAR},            CLIENT_VOUCHER_STATUS = #{row.clientVoucherStatus,jdbcType=VARCHAR},            CLIENT_TYPE = #{row.clientType,jdbcType=VARCHAR},            DOC_CLASS = #{row.docClass,jdbcType=VARCHAR},            CARD_PB_UNION_FLAG = #{row.cardPbUnionFlag,jdbcType=VARCHAR},            WITHDRAWAL_TYPE = #{row.withdrawalType,jdbcType=VARCHAR}

